// OpSet conformance: every case of tests/data/op_references.json (generated by scripts/gen_op_references.py from
// NumPy / PyTorch) is compiled and run end to end, and the results are compared with the references.
#include <ii/model.h>

#include "core/json.h"
#include "ir/op_schema.h"
#include "support/test_util.h"

#include <gtest/gtest.h>

#include <fstream>
#include <set>
#include <sstream>
#include <string>
#include <vector>

namespace ii {
namespace {

struct ConformanceCase {
    std::string name;
    std::string graph;
    std::vector<Tensor> inputs;
    std::vector<Tensor> outputs;
    ii_test::Tolerance tolerance;
};

Result<Tensor> decode_tensor(const Json& json) {
    const std::optional<DType> dtype = parse_dtype(json.find("dtype") ? json.find("dtype")->as_string() : "");
    if (!dtype) {
        return errors::data_corrupted("bad dtype");
    }
    Shape shape;
    for (const Json& dim : json.find("shape")->as_array()) {
        shape.push_back(*dim.as_int());
    }
    const std::optional<std::vector<std::uint8_t>> bytes = base64_decode(json.find("base64")->as_string());
    if (!bytes) {
        return errors::data_corrupted("bad base64");
    }
    return Tensor::from_bytes(*dtype, shape, bytes->data(), bytes->size());
}

std::vector<ConformanceCase> load_cases() {
    std::ifstream file(II_TEST_DATA_DIR "/op_references.json", std::ios::binary);
    std::stringstream buffer;
    buffer << file.rdbuf();
    Result<Json> document = Json::parse(buffer.str());
    std::vector<ConformanceCase> cases;
    if (!document.ok()) {
        return cases;
    }
    for (const Json& item : document->find("cases")->as_array()) {
        ConformanceCase c;
        c.name = item.find("name")->as_string();
        c.graph = item.find("graph")->as_string();
        for (const Json& t : item.find("inputs")->as_array()) {
            c.inputs.push_back(decode_tensor(t).value());
        }
        for (const Json& t : item.find("outputs")->as_array()) {
            c.outputs.push_back(decode_tensor(t).value());
        }
        c.tolerance = {item.find("rtol")->as_double(), item.find("atol")->as_double()};
        cases.push_back(std::move(c));
    }
    return cases;
}

const std::vector<ConformanceCase>& cases() {
    static const std::vector<ConformanceCase> loaded = load_cases();
    return loaded;
}

std::vector<std::string> case_names() {
    std::vector<std::string> names;
    for (const ConformanceCase& c : cases()) {
        names.push_back(c.name);
    }
    return names;
}

const ConformanceCase& find_case(const std::string& name) {
    for (const ConformanceCase& c : cases()) {
        if (c.name == name) {
            return c;
        }
    }
    static const ConformanceCase kNone;
    return kNone;
}

class ConformanceTest : public ::testing::TestWithParam<std::string> {};

void check_case(const ConformanceCase& c, const CompileOptions& options) {
    static const Context context = ii_test::test_context();
    const Result<Model> model = Model::from_text(context, c.graph);
    ASSERT_TRUE(model.ok()) << model.status().to_string() << "\n" << c.graph;
    const Result<std::vector<Tensor>> outputs = ii_test::run_model(*model, c.inputs, options);
    ASSERT_TRUE(outputs.ok()) << outputs.status().to_string() << "\n" << c.graph;
    ASSERT_EQ(outputs->size(), c.outputs.size());
    for (std::size_t i = 0; i < c.outputs.size(); ++i) {
        const std::string mismatch = ii_test::compare((*outputs)[i], c.outputs[i], c.tolerance);
        EXPECT_TRUE(mismatch.empty()) << "output " << i << ": " << mismatch << c.graph;
    }
}

TEST_P(ConformanceTest, MatchesReference) {
    check_case(find_case(GetParam()), {});
}

TEST_P(ConformanceTest, MatchesReferenceWithoutConstantFolding) {
    // With constant folding the inputs stay inputs anyway; this variant also covers decomposed composites.
    CompileOptions options;
    options.fold_constants = false;
    options.decompose_composites = true;
    const ConformanceCase& c = find_case(GetParam());
    ii_test::Tolerance tolerance = c.tolerance;
    // Decompositions round intermediate results to the working type: allow a few more ulps.
    tolerance.rtol = std::max(tolerance.rtol,
                              4 * ii_test::tolerance_for(c.outputs.empty() ? DType::kF32 : c.outputs[0].dtype()).rtol);
    tolerance.atol = std::max(tolerance.atol,
                              4 * ii_test::tolerance_for(c.outputs.empty() ? DType::kF32 : c.outputs[0].dtype()).atol);
    ConformanceCase relaxed = c;
    relaxed.tolerance = tolerance;
    check_case(relaxed, options);
}

INSTANTIATE_TEST_SUITE_P(OpSet, ConformanceTest, ::testing::ValuesIn(case_names()),
                         [](const ::testing::TestParamInfo<std::string>& param_info) { return param_info.param; });

TEST(ConformanceDataTest, CoversEveryOperation) {
    ASSERT_GT(cases().size(), 100u) << "tests/data/op_references.json is missing or invalid";
    std::set<std::string, std::less<>> covered;
    for (const ConformanceCase& c : cases()) {
        for (const auto& schema : ir::default_op_registry().all()) {
            if (c.graph.find(" = " + std::string(schema->name) + "(") != std::string::npos) {
                covered.insert(std::string(schema->name));
            }
        }
    }
    for (const auto& schema : ir::default_op_registry().all()) {
        EXPECT_TRUE(covered.contains(schema->name)) << "no conformance case for '" << schema->name << "'";
    }
}

}  // namespace
}  // namespace ii
